static NSURL *Root(void){NSURL *u=[NSURL fileURLWithPath:[NSHomeDirectory()stringByAppendingPathComponent:@"Library/Application Support/TurboIOPrivateAddon/WeRead"] isDirectory:YES];[NSFileManager.defaultManager createDirectoryAtURL:u withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700,NSFileProtectionKey:NSFileProtectionCompleteUntilFirstUserAuthentication} error:nil];return u;}
static void Field(uint8_t *p,NSUInteger cap,NSString *s){if(![s isKindOfClass:NSString.class])return;__block NSUInteger at=0;[s enumerateSubstringsInRange:NSMakeRange(0,s.length) options:NSStringEnumerationByComposedCharacterSequences usingBlock:^(NSString *c,NSRange a,NSRange b,BOOL *stop){if([c rangeOfCharacterFromSet:NSCharacterSet.controlCharacterSet].location!=NSNotFound)return;NSData *d=[c dataUsingEncoding:NSUTF8StringEncoding];if(at+d.length>=cap){*stop=YES;return;}memcpy(p+at,d.bytes,d.length);at+=d.length;}];}
static NSData *CoverPixels(NSData *data,BOOL *decoded){if(decoded)*decoded=NO;NSMutableData *out=[NSMutableData dataWithLength:WR_COVER_BYTES];uint8_t *p=out.mutableBytes;for(unsigned y=0;y<88;y++)for(unsigned x=0;x<64;x++)p[y*64+x]=(x==2||x==61||y==2||y==85)?150:12;
 if(!data)return out;CGImageSourceRef source=CGImageSourceCreateWithData((__bridge CFDataRef)data,(__bridge CFDictionaryRef)@{(id)kCGImageSourceShouldCache:@NO});if(!source)return out;
 NSDictionary *info=CFBridgingRelease(CGImageSourceCopyPropertiesAtIndex(source,0,NULL));uint64_t w=[info[(id)kCGImagePropertyPixelWidth]unsignedLongLongValue],h=[info[(id)kCGImagePropertyPixelHeight]unsignedLongLongValue];
 if(!w||!h||w>8192||h>8192||w*h>24000000){CFRelease(source);return out;}
 CGImageRef image=CGImageSourceCreateThumbnailAtIndex(source,0,(__bridge CFDictionaryRef)@{(id)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(id)kCGImageSourceThumbnailMaxPixelSize:@128,(id)kCGImageSourceCreateThumbnailWithTransform:@YES,(id)kCGImageSourceShouldCache:@NO});CFRelease(source);if(!image)return out;
 CGColorSpaceRef gray=CGColorSpaceCreateDeviceGray();CGContextRef ctx=CGBitmapContextCreate(p,64,88,8,64,gray,kCGImageAlphaNone);CGColorSpaceRelease(gray);if(ctx){CGContextSetInterpolationQuality(ctx,kCGInterpolationHigh);CGContextDrawImage(ctx,CGRectMake(0,0,64,88),image);CGContextRelease(ctx);if(decoded)*decoded=YES;}CGImageRelease(image);return out;
}
@interface TWLibrary:NSObject
@property TWReaderBridge *bridge;
@property NSMutableArray<NSMutableDictionary *> *books;
@property NSMutableArray<NSDictionary *> *coverResults;
@property NSDictionary *overview;
@property NSArray<NSString *> *lines;
@property NSData *pendingBody;
@property BOOL pendingSettings;
@property NSString *note,*mode;
@property NSUInteger selected,page,loadGeneration;
@property unsigned speed;
@property BOOL automatic,loading;
+ (instancetype)shared;
- (void)fetch;
- (void)stats;
- (void)shelf:(NSUInteger)first;
- (void)read:(NSUInteger)index row:(NSUInteger)row;
- (void)save;
- (void)cancelWeb;
@end
@implementation TWLibrary
+ (instancetype)shared{static TWLibrary *s;static dispatch_once_t once;dispatch_once(&once,^{s=[self new];});return s;}
- (instancetype)init{if((self=[super init])){_books=[NSMutableArray new];_bridge=[TWReaderBridge new];_speed=240;_mode=@"monthly";_note=@"Configure Key to synchronize WeReadBookshelf, or import local books first";
 id saved=[NSArray arrayWithContentsOfURL:[Root()URLByAppendingPathComponent:@"books.plist"]];if([saved isKindOfClass:NSArray.class]&&[saved count]<=1000)for(id b in saved)if([b isKindOfClass:NSDictionary.class]&&[b[@"title"]isKindOfClass:NSString.class])[_books addObject:[b mutableCopy]];
 if(!_books.count){
  for(unsigned i=0;i<9;i++){NSMutableString *text=[NSMutableString new];for(unsigned row=0;row<120;row++)[text appendFormat:@"Book %u, paragraph %u: This is an original reading test. The knob can be manually scrolled and pressed to pause or resume. Check seven three ninety two. \n",i+1,row+1];NSString *file=[NSUUID.UUID.UUIDString stringByAppendingPathExtension:@"txt"];if(![text writeToURL:[Root()URLByAppendingPathComponent:file] atomically:YES encoding:NSUTF8StringEncoding error:nil])break;[_books addObject:[@{@"id":NSUUID.UUID.UUIDString,@"title":[NSString stringWithFormat:@"Reading Test %u",i+1],@"author":@"Turbo IO original example",@"local":@YES,@"demo":@YES,@"file":file}mutableCopy]];}
  [self save];
 }
 unsigned speed=(unsigned)[NSUserDefaults.standardUserDefaults integerForKey:@"TurboWeReadSpeedV1"];if(speed>=30&&speed<=480)_speed=speed;_automatic=[NSUserDefaults.standardUserDefaults boolForKey:@"TurboWeReadAutoV1"];
 __weak typeof(self) weak=self;_bridge.command=^(NSDictionary *q){TWLibrary *s=weak;if(!s)return;unsigned event=[q[@"event"]unsignedIntValue];if(event==WR_SHELF)[s shelf:[q[@"value"]unsignedIntegerValue]];if(event==WR_BOOK){NSUInteger token=[q[@"value"]unsignedIntegerValue];if(token&&token<=s.books.count)[s read:token-1 row:0];}if(event==WR_WINDOW){s.automatic=[q[@"automatic"]boolValue];NSUInteger token=[q[@"token"]unsignedIntegerValue];if(token&&token<=s.books.count)[s read:token-1 row:[q[@"value"]unsignedIntegerValue]];}};
 [NSTimer scheduledTimerWithTimeInterval:.2 repeats:YES block:^(NSTimer *t){TWLibrary *s=weak;if(s.pendingBody&&s.bridge.active&&!s.bridge.busy){NSData *body=s.pendingBody;s.pendingBody=nil;[s.bridge sendBody:body];}if(s.pendingSettings&&s.bridge.active&&!s.bridge.busy){s.pendingSettings=NO;[s.bridge settings:s.speed automatic:s.automatic];}if(!s.bridge.active){s.pendingBody=nil;}[s.bridge pump];}];}return self;}
- (void)save{[self.books writeToURL:[Root()URLByAppendingPathComponent:@"books.plist"] atomically:YES];}
- (void)cancelWeb{self.pendingBody=nil;}
- (void)stats{NSString *mode=self.mode;TWRequest(@"/readdata/detail",@{@"mode":mode,@"baseTime":@0},^(NSDictionary *r,NSString *err){if(![self.mode isEqual:mode])return;self.overview=r?TWReadingOverview(r,mode):nil;if(err)self.note=err;});}
- (void)fetch{if(self.loading||self.bridge.active){self.note=@"Close glasses reading before refreshing bookshelf";return;}self.loading=YES;self.note=@"Getting Bookshelf…";
 TWRequest(@"/shelf/sync",@{},^(NSDictionary *r,NSString *err){self.loading=NO;if(err){self.note=err;return;}NSArray *books=r[@"books"],*albums=r[@"albums"];if(![books isKindOfClass:NSArray.class]||books.count>1000){self.note=@"The format or quantity returned by Bookshelf does not meet the limit";return;}
 NSMutableDictionary *old=[NSMutableDictionary new];NSMutableArray *local=[NSMutableArray new];for(NSDictionary *b in self.books){if(b[@"id"])old[b[@"id"]]=b;if(b[@"local"])[local addObject:[b mutableCopy]];}
 NSMutableArray *next=[NSMutableArray new];for(id b in books){if(![b isKindOfClass:NSDictionary.class]||![b[@"title"]isKindOfClass:NSString.class])continue;NSString *ident=[b[@"bookId"]description];if(!ident.length)continue;NSMutableDictionary *v=[@{@"id":ident,@"title":b[@"title"],@"author":[b[@"author"]isKindOfClass:NSString.class]?b[@"author"]:@"",@"cover":[b[@"cover"]isKindOfClass:NSString.class]?b[@"cover"]:@""}mutableCopy];if(old[ident][@"file"])v[@"file"]=old[ident][@"file"];[next addObject:v];}
 [next addObjectsFromArray:local];if(next.count>1000){self.note=@"Bookshelf limit reached (1000 books)";return;}self.books=next;self.lines=nil;self.selected=NSNotFound;[self save];NSUInteger audio=[albums isKindOfClass:NSArray.class]?albums.count:0;BOOL mp=[r[@"mp"]isKindOfClass:NSDictionary.class]&&[r[@"mp"]count]>0;self.note=[NSString stringWithFormat:@"Official Bookshelf %lu item (including %lu audio and %u article entry); the glasses only display e-books and native imports. The text needs to be imported into EPUB/TXT by yourself.",(unsigned long)(books.count+audio+mp),(unsigned long)audio,mp];[self stats];});
}
- (void)coverPage:(NSMutableData *)body first:(NSUInteger)first index:(NSUInteger)i generation:(NSUInteger)generation{if(generation!=self.loadGeneration||!self.bridge.active){self.loading=NO;return;}NSUInteger count=wr_u32(body.bytes+12);if(i>=count){self.loading=NO;self.pendingBody=body;NSUInteger missing=0;for(NSDictionary *r in self.coverResults)if(![r[@"decoded"]boolValue])missing++;
 self.note=[NSString stringWithFormat:@"Page: %lu books · %.1f KB · %lu packets%@",(unsigned long)count,body.length/1024.0,(unsigned long)(2+(body.length+479)/480),missing?[NSString stringWithFormat:@";%lu covers occupy space, see cover diagnosis for details",(unsigned long)missing]:@";The covers have been reduced to 64×88"];
 NSData *report=[NSJSONSerialization dataWithJSONObject:@{@"numericMetadataOnly":@YES,@"page":@(first/4+1),@"results":self.coverResults?:@[]} options:NSJSONWritingPrettyPrinted error:nil];[report writeToURL:[Root()URLByAppendingPathComponent:@"cover-status.json"] atomically:YES];return;}
 NSDictionary *book=self.books[first+i];TWCover(book[@"cover"],^(NSData *image,NSString *error){if(generation!=self.loadGeneration)return;BOOL decoded=NO;NSData *pixels=CoverPixels(image,&decoded);[self.coverResults addObject:@{@"index":@(first+i),@"host":[NSURL URLWithString:book[@"cover"]?:@""].host?:@"",@"downloadBytes":@(image.length),@"sentBytes":@(pixels.length),@"decoded":@(decoded),@"error":error?:(decoded?@"":@"The image cannot be decoded or the size exceeds the limit")}];uint8_t *card=(uint8_t *)body.mutableBytes+64+i*WR_CARD_BYTES;memcpy(card+192,pixels.bytes,pixels.length);[self coverPage:body first:first index:i+1 generation:generation];});
}
- (void)shelf:(NSUInteger)first{[self cancelWeb];if(self.loading||!self.books.count||first>=self.books.count){self.note=self.books.count?@"Loading, please wait":@"Bookshelf is empty, please synchronize or import";return;}if(!self.bridge.active){[self.bridge open];return;}if(self.bridge.busy){self.note=@"Transmitting, waiting for receipt and trying again";return;}first=first/4*4;self.page=first;NSUInteger count=MIN(4,self.books.count-first);NSMutableData *d=[NSMutableData dataWithLength:64+count*WR_CARD_BYTES];uint8_t *p=d.mutableBytes;wr_put(p,1);wr_put(p+4,(uint32_t)first);wr_put(p+8,(uint32_t)self.books.count);wr_put(p+12,(uint32_t)count);for(NSUInteger i=0;i<count;i++){uint8_t *c=p+64+i*WR_CARD_BYTES;NSDictionary *b=self.books[first+i];Field(c,96,b[@"title"]);Field(c+96,64,b[@"author"]);wr_put(c+160,(uint32_t)(first+i+1));}
 self.loading=YES;self.coverResults=[NSMutableArray new];self.note=@"Downloading and processing covers…";[self coverPage:d first:first index:0 generation:++self.loadGeneration];}
- (void)read:(NSUInteger)index row:(NSUInteger)row{if(index>=self.books.count||self.loading||self.bridge.busy)return;NSDictionary *b=self.books[index];NSString *file=b[@"file"];[self cancelWeb];if(![file isKindOfClass:NSString.class]||![file isEqual:file.lastPathComponent]||![file.pathExtension isEqual:@"txt"]){self.note=@"Please import the EPUB/TXT text that you have permission to use first";self.pendingBody=TWReaderWindow(@[@"Need to import the text natively",@"Mobile: Import EPUB/TXT",@"EPUB/TXT can also be imported",@"Long press to return to Bookshelf"],b[@"title"],(uint32_t)index+1,0,30,NO);return;}
 if(index!=self.selected||!self.lines){NSString *text=[NSString stringWithContentsOfURL:[Root()URLByAppendingPathComponent:file] encoding:NSUTF8StringEncoding error:nil];self.lines=TWReadingLines(text);self.selected=index;}if(!self.lines){self.note=@"The native text does not exist or exceeds the typesetting limit";return;}NSData *body=TWReaderWindow(self.lines,b[@"title"],(uint32_t)index+1,MIN(row,self.lines.count-1),self.speed,self.automatic);if(body){self.pendingBody=body;self.note=@"Send native import text · Non-WeRead full-text interface";}}
@end
BOOL TWReaderConsume(NSDictionary *e){return [[TWLibrary shared].bridge consume:e];}
BOOL TWReaderPauseForOTA(void){TWLibrary *s=TWLibrary.shared;[s cancelWeb];if(!s.bridge.active&&!s.bridge.busy)return YES;s.loadGeneration++;s.loading=NO;s.pendingBody=nil;s.pendingSettings=NO;[s.bridge close];return NO;}
void TWReaderPauseForVoice(void){(void)TWReaderPauseForOTA();}

#include "ReaderEditorial.inc"
@interface TWController:UITableViewController<UIDocumentPickerDelegate>
@property TWLibrary *library;
@property NSTimer *timer;
@property NSUInteger importIndex;
@property NSString *lastUISignature;
@property UILabel *progressLabel;
@property UIBarButtonItem *readerStop;
@property NSMutableIndexSet *expanded;
@end
@implementation TWController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"WeRead";self.expanded=[NSMutableIndexSet indexSetWithIndexesInRange:NSMakeRange(1,1)];[self.expanded addIndex:3];TIOStyleResearchTable(self);self.library=TWLibrary.shared;self.importIndex=NSNotFound;self.tableView.backgroundColor=TIOPaper();self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithImage:[UIImage systemImageNamed:@"ellipsis.circle"] style:UIBarButtonItemStylePlain target:self action:@selector(key)];
 self.tableView.tableHeaderView=TIOFeatureHeader(@"Reading on the Go",@"Sync bookshelf, pick a book. Text loads on demand.",@"reading");self.readerStop=[[UIBarButtonItem alloc]initWithImage:[UIImage systemImageNamed:@"stop.circle"] style:UIBarButtonItemStylePlain target:self action:@selector(stopReadingFromBar)];self.readerStop.tintColor=UIColor.systemRedColor;self.readerStop.accessibilityLabel=@"stop glasses reading";self.readerStop.enabled=self.library.bridge.active||self.library.bridge.busy;self.navigationItem.rightBarButtonItems=@[self.navigationItem.rightBarButtonItem,self.readerStop];[self installReaderProgress];[self refreshEditorialState];}
- (void)viewWillAppear:(BOOL)a{[super viewWillAppear:a];[self.timer invalidate];[self refreshEditorialState];__weak typeof(self) w=self;self.timer=[NSTimer timerWithTimeInterval:.5 repeats:YES block:^(NSTimer *t){[w refreshEditorialState];}];[NSRunLoop.mainRunLoop addTimer:self.timer forMode:NSRunLoopCommonModes];}
- (void)viewDidDisappear:(BOOL)a{[super viewDidDisappear:a];[self.timer invalidate];self.timer=nil;}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)v{return 4;}
- (NSInteger)sourceSection:(NSInteger)s{return (NSInteger[]){1,3,2,0}[s];}
#include "ReaderProgress.inc"

- (void)stopReadingFromBar{self.library.loadGeneration++;self.library.loading=NO;self.library.pendingBody=nil;self.library.pendingSettings=NO;[self.library.bridge close];[self refreshEditorialState];}

- (NSInteger)tableView:(UITableView *)v numberOfRowsInSection:(NSInteger)s{s=[self sourceSection:s];if(s==1)return 2;if(s==3)return MAX(1,(self.library.books.count+1)/2);if(s==2)return [self.expanded containsIndex:s]?6:2;return [self.expanded containsIndex:s]?(s==0?3:s==1?2:self.library.books.count):0;}
- (UIView *)tableView:(UITableView *)t viewForHeaderInSection:(NSInteger)s{s=[self sourceSection:s];if(s==1){UILabel *label=[UILabel new];label.text=@"Sync status";label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleSubheadline];label.textColor=TIOInk();return label;}if(s==3){__weak typeof(self) weak=self;return TIOFoldHeader(@"My Bookshelf · Click here to sync",NO,^{[weak syncShelfFromHeader];});}__weak typeof(self) w=self;return TIOFoldHeader(@[@"reading statistics",@"Sync status",@"Reading settings",@"My Bookshelf"][s],[self.expanded containsIndex:s],^{if([w.expanded containsIndex:s])[w.expanded removeIndex:s];else [w.expanded addIndex:s];[w.tableView reloadData];});}
- (CGFloat)tableView:(UITableView *)t heightForHeaderInSection:(NSInteger)s{return 54;}
- (NSIndexPath *)sourceIndex:(NSIndexPath *)i{i=[NSIndexPath indexPathForRow:i.row inSection:[self sourceSection:i.section]];return i.section==2&&![self.expanded containsIndex:2]?[NSIndexPath indexPathForRow:i.row==0?1:4 inSection:2]:i;}

- (NSString *)tableView:(UITableView *)v titleForFooterInSection:(NSInteger)s{s=[self sourceSection:s];if(![self.expanded containsIndex:s])return nil;if(s==0)return @"The official duration includes reading and listening; the depth is only a reference for reading input and does not represent the level of understanding.";if(s==3)return @"There are four books per page in the glasses; scroll the knob to select a book, then press to open when it stops. The Reading knob scrolls manually, press to switch to automatic; press and hold to return to the original Bookshelf page, and press and hold again to exit. The public version only provides native EPUB/TXT text import.";return nil;}
- (UITableViewCell *)tableView:(UITableView *)v cellForRowAtIndexPath:(NSIndexPath *)i{if(i.section==1)return [self shelfCell:i];i=[self sourceIndex:i];UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];c.textLabel.numberOfLines=0;c.detailTextLabel.numberOfLines=0;c.detailTextLabel.textColor=UIColor.secondaryLabelColor;TWLibrary *s=self.library;
 if(i.section==0){NSDictionary *o=s.overview;if(i.row==0){c.textLabel.text=[NSString stringWithFormat:@"%@ · %@ · %@",o[@"period"]?:@"This Month",o[@"duration"]?:@"No Data",o[@"readDaysText"]?:@"No Data"];c.detailTextLabel.text=@"Click here to switch: this week / this month / this year / cumulative";c.imageView.image=[UIImage systemImageNamed:@"chart.bar.xaxis"];}
 if(i.row==1){NSArray *categories=o[@"categories"];NSMutableArray *parts=[NSMutableArray new];for(NSDictionary *r in categories)[parts addObject:[NSString stringWithFormat:@"%@ %@",r[@"title"],r[@"duration"]]];c.textLabel.text=@"Reading preferences";c.detailTextLabel.text=parts.count?[parts componentsJoinedByString:@" · "]:@"Not enough data yet";c.imageView.image=[UIImage systemImageNamed:@"sparkles"];}
 if(i.row==2){NSMutableArray *parts=[NSMutableArray new];for(NSDictionary *r in o[@"depthEvidence"])[parts addObject:[r[@"label"]stringByAppendingString:r[@"value"]]];c.textLabel.text=@"Reading Engagement";c.detailTextLabel.text=parts.count?[parts componentsJoinedByString:@" · "]:@"No statistics of reading/notes yet";c.imageView.image=[UIImage systemImageNamed:@"text.book.closed"];}}
 if(i.section==1){c.textLabel.text=i.row==0?s.note:[self transferStatusText];c.imageView.image=[UIImage systemImageNamed:i.row==0?@"books.vertical":@"eyeglasses"];c.selectionStyle=UITableViewCellSelectionStyleNone;}
 if(i.section==2){if(i.row==4)c.textLabel.textColor=UIColor.systemRedColor;c.textLabel.text=@[@"Sync WeReadBookshelf",@"Send four bookshelf to glasses",@"Import EPUB/TXT",[NSString stringWithFormat:@"%@ · %u words/minute",s.automatic?@"autoscroll":@"Manual reading",s.speed],@"Exit glasses reading",@"Added 9 original test books · No Key required"][i.row];c.imageView.image=[UIImage systemImageNamed:@[@"arrow.triangle.2.circlepath",@"paperplane",@"square.and.arrow.down",@"speedometer",@"stop.circle",@"testtube.2"][i.row]];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}
 if(i.section==3){NSDictionary *b=s.books[i.row];c.textLabel.text=[NSString stringWithFormat:@"%ld. %@",(long)i.row+1,b[@"title"]];c.detailTextLabel.text=[NSString stringWithFormat:@"%@ · %@",b[@"author"]?:@"",b[@"file"]?@"Already has local text":@"Web page reading/can import text"];c.imageView.image=[UIImage systemImageNamed:b[@"file"]?@"book.closed.fill":@"book.closed"];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}return c;
}
- (UITableViewCell *)shelfCell:(NSIndexPath *)path{
 UITableViewCell *cell=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];cell.selectionStyle=UITableViewCellSelectionStyleNone;
 UIStackView *row=[UIStackView new];row.axis=UILayoutConstraintAxisHorizontal;row.distribution=UIStackViewDistributionFillEqually;row.spacing=12;row.translatesAutoresizingMaskIntoConstraints=NO;[cell.contentView addSubview:row];
 [NSLayoutConstraint activateConstraints:@[[row.leadingAnchor constraintEqualToAnchor:cell.contentView.leadingAnchor constant:8],[row.trailingAnchor constraintEqualToAnchor:cell.contentView.trailingAnchor constant:-8],[row.topAnchor constraintEqualToAnchor:cell.contentView.topAnchor constant:8],[row.bottomAnchor constraintEqualToAnchor:cell.contentView.bottomAnchor constant:-8]]];
 if(!self.library.books.count){[row addArrangedSubview:TIOEmptyState(@"books.vertical",@"Bookshelf is empty",@"Read below to set up syncing Bookshelf, or import EPUB/TXT.")];return cell;}
 for(NSUInteger slot=0;slot<2;slot++){NSUInteger index=path.row*2+slot;if(index>=self.library.books.count){[row addArrangedSubview:[UIView new]];continue;}NSDictionary *book=self.library.books[index];NSString *ident=book[@"id"];__weak typeof(self) weak=self;UIControl *tile=TIOBookTile(book,^{if(index<weak.library.books.count&&[weak.library.books[index][@"id"]isEqual:ident])[weak openBookAtIndex:index];});tile.accessibilityIdentifier=[NSString stringWithFormat:@"reader-book-%lu",(unsigned long)index];[row addArrangedSubview:tile];}return cell;
}
- (void)syncShelfFromHeader{[self.library fetch];[self refreshEditorialState];}
- (void)alert:(NSString *)message{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"WeRead" message:message preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (void)key{[self gatewayKey];}
- (void)gatewayKey{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"WeRead API Key" message:@"Only saved in this phone keychain, not sent to glasses or models. Leave blank to clear." preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.secureTextEntry=YES;f.placeholder=TWAPIKey().length?@"Configured, enter new value to replace":@"wrk-…";f.autocorrectionType=UITextAutocorrectionTypeNo;f.autocapitalizationType=UITextAutocapitalizationTypeNone;}];[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *v){self.library.note=TWSetAPIKey(a.textFields[0].text)?@"Configuration has been updated":@"Failed to save or format does not match";}]];[self presentViewController:a animated:YES completion:nil];}
- (void)importBook:(NSUInteger)index{if(self.library.bridge.active||self.library.bridge.busy){[self alert:@"Please exit Glass Reading first and then import it to avoid replacing the current text."];return;}self.importIndex=index;UIDocumentPickerViewController *p=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypePlainText,[UTType typeWithFilenameExtension:@"epub"]] asCopy:YES];p.delegate=self;p.allowsMultipleSelection=NO;[self presentViewController:p animated:YES completion:nil];}
- (void)documentPicker:(UIDocumentPickerViewController *)p didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{NSURL *u=urls.firstObject;if(!u)return;NSUInteger index=self.importIndex;self.library.loading=YES;self.library.note=@"Verifying and importing text...";dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{BOOL scope=[u startAccessingSecurityScopedResource];NSNumber *size;[u getResourceValue:&size forKey:NSURLFileSizeKey error:nil];NSData *d=size&&size.unsignedLongLongValue<=24*1024*1024?[NSData dataWithContentsOfURL:u options:NSDataReadingMappedIfSafe error:nil]:nil;NSString *error,*text=TWImportBook(d,u.pathExtension,&error);NSArray *lines=text?TWReadingLines(text):nil;if(scope)[u stopAccessingSecurityScopedResource];dispatch_async(dispatch_get_main_queue(),^{self.library.loading=NO;if(!lines){self.library.note=error?:@"The text is empty or the layout exceeds the limit";return;}if(index!=NSNotFound&&index>=self.library.books.count){self.library.note=@"Bookshelf has changed, reselect the import target";return;}NSString *file=[NSUUID.UUID.UUIDString stringByAppendingPathExtension:@"txt"];if(![text writeToURL:[Root()URLByAppendingPathComponent:file] atomically:YES encoding:NSUTF8StringEncoding error:nil]){self.library.note=@"Failed to save text";return;}if(index==NSNotFound){if(self.library.books.count>=1000){self.library.note=@"Bookshelf has reached the limit of 1,000 books";return;}[self.library.books addObject:[@{@"id":NSUUID.UUID.UUIDString,@"title":u.lastPathComponent.stringByDeletingPathExtension,@"author":@"Imported Locally",@"local":@YES,@"file":file}mutableCopy]];}else self.library.books[index][@"file"]=file;self.library.lines=nil;[self.library save];self.library.note=[NSString stringWithFormat:@"Local text saved · %lu line; will not be uploaded to WeRead",(unsigned long)lines.count];});});}
- (void)controls{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Scroll Speed" message:@"30–480 words/minute; knob operation pauses automatic scrolling." preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.keyboardType=UIKeyboardTypeNumberPad;f.text=[NSString stringWithFormat:@"%u",self.library.speed];}];for(NSNumber *autoValue in @[@NO,@YES]){[a addAction:[UIAlertAction actionWithTitle:autoValue.boolValue?@"autoscroll":@"Manual reading" style:UIAlertActionStyleDefault handler:^(UIAlertAction *v){NSInteger speed=a.textFields[0].text.integerValue;if(speed<30||speed>480){[self alert:@"Speed ​​should be 30–480 words/minute"];return;}self.library.speed=(unsigned)speed;self.library.automatic=autoValue.boolValue;[NSUserDefaults.standardUserDefaults setInteger:speed forKey:@"TurboWeReadSpeedV1"];[NSUserDefaults.standardUserDefaults setBool:autoValue.boolValue forKey:@"TurboWeReadAutoV1"];self.library.pendingSettings=YES;}]];}[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (void)demo{TWLibrary *s=self.library;if(s.bridge.active||s.bridge.busy||s.loading){[self alert:@"Exit Glass Reading first and wait for the import/synchronization to complete."];return;}for(NSDictionary *b in s.books)if(b[@"demo"]){[self alert:@"The test book is already in Bookshelf and will not be added again."];return;}if(s.books.count>991)return;
 for(unsigned i=0;i<9;i++){NSMutableString *text=[NSMutableString new];for(unsigned row=0;row<120;row++)[text appendFormat:@"Book %u, paragraph %u: This is an original reading test. The knob can be manually scrolled and pressed to pause or resume. Check seven three ninety two. \n",i+1,row+1];NSString *file=[NSUUID.UUID.UUIDString stringByAppendingPathExtension:@"txt"];if(![text writeToURL:[Root()URLByAppendingPathComponent:file] atomically:YES encoding:NSUTF8StringEncoding error:nil])break;[s.books addObject:[@{@"id":NSUUID.UUID.UUIDString,@"title":[NSString stringWithFormat:@"Reading Test %u",i+1],@"author":@"Turbo IO original example",@"local":@YES,@"demo":@YES,@"file":file}mutableCopy]];}[s save];s.note=@"Test books have been added: used for pagination, opening, flipping and long text scrolling acceptance of four books";}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(i.section==1)return;i=[self sourceIndex:i];if(i.section==0&&i.row==0){NSArray *modes=@[@"weekly",@"monthly",@"annually",@"overall"];NSUInteger n=[modes indexOfObject:self.library.mode];self.library.mode=modes[(n+1)%4];[self.library stats];}
 if(i.section==2){if(i.row==0)[self.library fetch];if(i.row==1){if(!TMMusicPauseForOTA()||!TNVPauseForOTA()){[self alert:@"Please end Music or Navigation and try again"];return;}[self.library shelf:0];}if(i.row==2)[self importBook:NSNotFound];if(i.row==3)[self controls];if(i.row==4){self.library.loadGeneration++;self.library.loading=NO;self.library.pendingBody=nil;self.library.pendingSettings=NO;[self.library.bridge close];}if(i.row==5)[self demo];}
}
- (void)openBookAtIndex:(NSUInteger)index{if(index>=self.library.books.count)return;NSDictionary *book=self.library.books[index];UIAlertController *a=[UIAlertController alertControllerWithTitle:book[@"title"] message:@"Please import the EPUB/TXT text that you have permission to use; the Bookshelf interface does not provide full text." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"Import corresponding EPUB / TXT" style:UIAlertActionStyleDefault handler:^(UIAlertAction *v){[self importBook:index];}]];[a addAction:[UIAlertAction actionWithTitle:@"Open this book with glasses" style:UIAlertActionStyleDefault handler:^(UIAlertAction *v){if(!self.library.bridge.active){[self alert:@"Send Bookshelf first to establish a reading session, and then open this book."];return;}[self.library read:index row:0];}]];[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}

@end
UIViewController *TWReaderController(void){return [[TWController alloc]initWithStyle:UITableViewStyleInsetGrouped];}
void TWReaderProbeIfRequested(void){if(![NSProcessInfo.processInfo.environment[@"TIO_WEREAD_PROBE"]isEqual:@"READ01"])return;
 UIWindow *window=nil;for(UIScene *scene in UIApplication.sharedApplication.connectedScenes)if([scene isKindOfClass:UIWindowScene.class])for(UIWindow *w in ((UIWindowScene *)scene).windows)if(w.isKeyWindow)window=w;
 UIViewController *root=window.rootViewController;while(root.presentedViewController)root=root.presentedViewController;if(!root)return;UIViewController *page=TWReaderController();UINavigationController *nav=[[UINavigationController alloc]initWithRootViewController:page];nav.modalPresentationStyle=UIModalPresentationFullScreen;
 [root presentViewController:nav animated:NO completion:^{dispatch_after(dispatch_time(DISPATCH_TIME_NOW,2*NSEC_PER_SEC),dispatch_get_main_queue(),^{
  UITableView *table=((UITableViewController *)page).tableView;BOOL visible=page.isViewLoaded&&page.view.window!=nil;
  NSDictionary *report=@{@"build":@"WEREAD-PHONE-03",@"visible":@(visible),@"sections":@(table.numberOfSections),@"controls":@([table numberOfRowsInSection:2]),@"keyConfigured":@(TWAPIKey().length>0),@"probeNetworkRequests":@0,@"probeGlassesWrites":@0,@"firmwareWritten":@NO};
  NSData *d=[NSJSONSerialization dataWithJSONObject:report options:NSJSONWritingPrettyPrinted error:nil];[d writeToURL:[Root()URLByAppendingPathComponent:@"probe.json"] atomically:YES];
  if(visible){UIGraphicsImageRenderer *renderer=[[UIGraphicsImageRenderer alloc]initWithBounds:page.view.bounds];UIImage *image=[renderer imageWithActions:^(UIGraphicsImageRendererContext *c){[page.view drawViewHierarchyInRect:page.view.bounds afterScreenUpdates:YES];}];[UIImagePNGRepresentation(image)writeToURL:[Root()URLByAppendingPathComponent:@"preview.png"] atomically:YES];}
 });}];
}
